"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6296],{9166(e){e.exports=JSON.parse('{"title":"Node.js\ub97c \uc798 \uc4f0\ub294 9\uac00\uc9c0 \uc6d0\uce59","date":"2024-10-04","coverUrl":null,"html":"<h2 data-notion-block-id=\\"05d2a6bf-9690-4f4f-b082-2d82e2b22b85\\" id=\\"05d2a6bf-9690-4f4f-b082-2d82e2b22b85\\">Node.js\ub97c \uc798 \uc4f0\ub294 9\uac00\uc9c0 \uc6d0\uce59</h2><a href=\\"https://www.platformatichq.com/node-principles\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.platformatichq.com/node-principles</a><p data-notion-block-id=\\"0ad28543-0405-4394-8c11-12ebc71a6279\\">Node.js\ub77c\uace0 \ud55c\uc815\uc9c0\uc5c8\uc9c0\ub9cc \uc774 \uc6d0\uce59\uc740 JS \uc804\ubc18\uc5d0 \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc5d0 \uaf2d \ubd24\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uc6d0\uce59\uc774\ub77c \ub418\uc5b4\uc788\uae30\uc5d0 \uc5b4\ub5bb\uac8c \ub2e8\uacc4\uc801\uc73c\ub85c \uc9c4\ud589\ud560\uc9c0\ub294 \uc801\ud600\uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubaa8\ub450\uac00 \ub0a9\ub4dd\ud560\ub9cc\ud55c \uc6d0\uce59\ub4e4\uc774\uae30 \ub54c\ubb38\uc5d0 \ud56d\uc0c1 \uc0dd\uac01\ud558\uba74\uc11c \uc81c\ud488\uc758 \uc9c4\ud589\ubc29\ud5a5\uc744 \uc124\uc815\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f1823c67-4e68-4176-8c43-08d97f56c102\\" id=\\"f1823c67-4e68-4176-8c43-08d97f56c102\\">\uc870\uac74\ubb38\uc758 \ubcf5\uc7a1\ud568\uc744 \ud478\ub294 \ubc29\ubc95</h2><a href=\\"https://tkdodo.eu/blog/component-composition-is-great-btw\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/component-composition-is-great-btw</a><p data-notion-block-id=\\"33edd06c-a049-4a72-8bcb-fd61f0ae2642\\">\uc870\uac74\ubb38\uc758 \ubcf5\uc7a1\ud568(\uc5ec\uae30\uc11c\ub294 \uc870\uac74\ubd80 \ub80c\ub354\ub9c1)\uc744 \ud478\ub294 \ubc29\ubc95\uc73c\ub85c \uc870\uae30 \ubc18\ud658(early return)\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc694\uad6c\uc0ac\ud56d\uc744 \uc798 \ubd84\uc11d\ud558\uc5ec \uc870\uac74\ubd80 \ub80c\ub354\ub9c1\uc744 \ub0a8\ubc1c\ud558\ub294 \uac83\uc744 \ub9c9\uc790\ub294 \uae00\uc785\ub2c8\ub2e4. \uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c \uc870\uae30 \ubc18\ud658\ubcf4\ub2e4 \ubd84\ub9ac, \ud639\uc740 \uaca9\ub9ac\uac00 \ub098\uc744 \uc218\ub3c4 \uc788\uc73c\ubbc0\ub85c \uc5ec\uae30\uc11c \uc81c\uc2dc\ud558\ub294 \ubd84\ud574, \uadf8\ub9ac\uace0 \ubd84\uc11d\uc774 \uac00\uc7a5 \uc911\uc694\ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"4cfc7e8b-83bf-4c1d-bd47-241af33dc359\\" id=\\"4cfc7e8b-83bf-4c1d-bd47-241af33dc359\\"><code>content-visibility</code>\ub85c \uac00\uc0c1\ud654 \ub300\uc2e0\ud558\uae30</h2><a href=\\"https://nolanlawson.com/2024/09/18/improving-rendering-performance-with-css-content-visibility/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nolanlawson.com/2024/09/18/improving-rendering-performance-with-css-content-visibility/</a><p data-notion-block-id=\\"b80ddc79-80d7-4713-976a-d7421554c115\\">Virtualization \ub300\uc2e0\uc5d0 <code>content-visibility</code>\uc744 \uc0ac\uc6a9\ud574\uc11c \uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \uc9c4\ud589\ud55c \uac04\ub2e8\ud55c \ud6c4\uae30\uc785\ub2c8\ub2e4. \uac00\uc0c1\ud654\ub294 UI \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \uc885\uc18d\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ucc3e\uc544 \uc0ac\uc6a9\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \uc798 \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\ub370, <code>content-visibility</code>\ub77c\ub294 \ud45c\uc900\uc744 \uc0ac\uc6a9\ud574\ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc544\ubcf4\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"58ec177d-c34a-4fa9-ac29-9d59338b4cd6\\" id=\\"58ec177d-c34a-4fa9-ac29-9d59338b4cd6\\"><code>AbortController</code> \ub9c8\uc2a4\ud130\ud558\uae30</h2><a href=\\"https://kettanaito.com/blog/dont-sleep-on-abort-controller\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kettanaito.com/blog/dont-sleep-on-abort-controller</a><p data-notion-block-id=\\"8c6fb97c-97d5-4527-9be3-4ddd4f97dda8\\">\ub9ce\uc774 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 <code>AbortController</code>\ub97c <code>fetch</code> API \ud638\ucd9c \uc911\uac04\uc5d0 \uc911\ub2e8\ud558\ub294 \uc77c \uc678\uc5d0  \uc5b4\ub290 \uacf3\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"287d88a5-2bad-4693-b11b-bda004671758\\" id=\\"287d88a5-2bad-4693-b11b-bda004671758\\">React\uc5d0\uc11c URL \ub2e4\ub8e8\uae30</h2><a href=\\"https://buildui.com/posts/how-to-control-a-react-component-with-the-url\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buildui.com/posts/how-to-control-a-react-component-with-the-url</a><p data-notion-block-id=\\"86012465-3725-4600-b20e-3e8daf53ed29\\">React\uc5d0\uc11c \ub9ce\uc774 \uc2e4\uc218\ud558\ub294 \ubd80\ubd84 \uc911 \ud558\ub098\uac00 URL\uc744 <code>useState</code>\uc640 \ud568\uaed8 \ub2e4\ub8e8\uac8c \ub418\uc5b4\uc11c \uacbd\uc6b0\uc5d0 \ub530\ub77c \ubd88\uc77c\uce58\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\ub2e4\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 React\uc5d0\uc11c, \ud639\uc740 \ub2e4\ub978 UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud560 \ub54c Single of truth\ub97c \ud56d\uc0c1 \uae30\uc5b5\ud558\uba74\uc11c \ucf54\ub4dc\ub97c \uc791\uc131\ud574\uc57c \ud55c\ub2e4\ub294 \uad50\ud6c8\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"0def01e9-bf2a-4c0e-879e-900b661a94af\\" id=\\"0def01e9-bf2a-4c0e-879e-900b661a94af\\">\ube0c\ub77c\uc6b0\uc800\ub294 \uaf64\ub098 \ub9ce\uc740 \uae30\ub2a5\uc744 \uc81c\uacf5\ud55c\ub2e4</h2><a href=\\"https://htmx.org/essays/you-cant/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://htmx.org/essays/you-cant/</a><p data-notion-block-id=\\"613845c0-3774-441a-9d5a-b6412d0f56ad\\">SPA \uae30\ubc18 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uaf2d \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\ub294 \uc8fc\uc7a5\ub4e4\uc744 \uc5ec\ub7ec \ube0c\ub77c\uc6b0\uc800 \ud45c\uc900 API\ub97c \uae30\ubc18\uc73c\ub85c \ubc18\ubc15\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 MPA \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc744 \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\uace0 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc5ec\uae30\uc11c \uc81c\uacf5\ud558\ub294 \uae30\uc220\ub4e4\uc744 \ud55c \ubc88 \ubcfc\ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ub300\ud45c\uc801\uc73c\ub85c Service Worker\ub97c \uc798 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 <code>workbox</code>\uc640 \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ee307831cb464aafb912fff97004d37e#9104b914-c2e2-4996-84f6-a8cb82cb8a42\\"><code>Speculation Rules API</code></a>\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"20901248-8a54-4e74-9f12-af3aaf5d6c91\\" id=\\"20901248-8a54-4e74-9f12-af3aaf5d6c91\\">\uc555\ucd95\uc5d0 \ub300\ud55c \uace0\ubbfc</h2><a href=\\"https://discord.com/blog/how-discord-reduced-websocket-traffic-by-40-percent\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://discord.com/blog/how-discord-reduced-websocket-traffic-by-40-percent</a><p data-notion-block-id=\\"b9cdd7ff-02bc-4efd-99b6-a3a6e7d87f9c\\">Websocket \ud2b8\ub798\ud53d\uc744 \ub0ae\ucd94\uae30 \uc704\ud55c \ub300\ud55c \uace0\ubbfc\uacfc \ud574\uacb0\ud55c \uacfc\uc815\uc744 \uc801\uc740 \uae00\uc785\ub2c8\ub2e4. \uc555\ucd95 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud1b5\ud55c \ud398\uc774\ub85c\ub4dc \uc555\ucd95, \ud2b8\ub798\ud53d\uc744 \uc904\uc774\uae30 \uc704\ud55c \ud328\uc2dc\ube0c \uc138\uc158\uacfc \uc77c\ubc18 \uc138\uc158 \uad6c\ubd84\uac19\uc740 \uc5ec\ub7ec\uac00\uc9c0 \uae30\uc220\uc744 \uc605\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"26743a45-cbc2-42a8-b237-d6cd95d85380\\" id=\\"26743a45-cbc2-42a8-b237-d6cd95d85380\\">JavaScript\uc5d0\uc11c \ud0c0\uc785 \uae30\ubc18 \ub9b0\ud2b8\uc758 \ud604\uc7ac</h2><a href=\\"https://www.joshuakgoldberg.com/blog/why-typed-linting-needs-typescript-today/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshuakgoldberg.com/blog/why-typed-linting-needs-typescript-today/</a><p data-notion-block-id=\\"de866c36-4dcd-4d51-840d-4548589cdd5a\\">TypeScript \uae30\ubc18 \ub9b0\ud130\uc758 \uc0dd\ud0dc\uacc4\ub4e4\uc758 \uace0\ucda9\uc744 \ubaa8\ub450 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. swc\uc640 esbuild\ucc98\ub7fc \ud2b8\ub79c\uc2a4\ud30c\uc77c\ub7ec\uac00 \uc548\uc815\ud654\ub418\uc5b4 \ub098\uc624\uc9c0 \uc54a\ub294 \uc774\uc720, \uadf8\ub9ac\uace0 <code>typescript-eslint</code>\ub294 \uc5b4\ub5a4 \ub178\ub825\uc744 \ud558\ub294\uc9c0 \uc5ff\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d0e90363-6363-4cee-80b4-4b5891faf03f\\" id=\\"d0e90363-6363-4cee-80b4-4b5891faf03f\\">\ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \uae30\uc220 \uc0b4\ud3b4\ubcf4\uae30</h2><a href=\\"https://www.joshwcomeau.com/blog/how-i-built-my-blog-v2/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/blog/how-i-built-my-blog-v2/</a><a href=\\"https://www.trevorlasn.com/blog/whats-new-in-express-5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.trevorlasn.com/blog/whats-new-in-express-5</a><a href=\\"https://developer.chrome.com/blog/new-in-chrome-129\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/new-in-chrome-129</a><p data-notion-block-id=\\"cd462696-72bc-434f-943c-af102f41df75\\">\uccab \uae00\uc740 \ube14\ub85c\uadf8\uc5d0 \uc801\uc6a9\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \uae30\uc220\uc744 \uc0b4\ud3b4\ubcf4\uba74\uc11c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uac00\ubccd\uac8c \uc774\ub7f0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc788\uad6c\ub098 \uc0b4\ud3b4\ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 express.js 5\uac00 \uc5b4\ub5a4 \uac83\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc138\ubc88\uc9f8 \uae00\uc740 Chrome 129\ubc84\uc804\uc5d0 \uc0c8\ub85c\uc6b4 \uac83\uc774 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8033-a90c-e3ad6ea49f73\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358</a> <code>interpolate-size</code>\uac00 \ub208\uc5d0 \ub744\ub124\uc694.</p><h2 data-notion-block-id=\\"5255ceeb-1346-4ccb-8554-6aa511e72bf8\\" id=\\"5255ceeb-1346-4ccb-8554-6aa511e72bf8\\">\uc138\uc0c1 \uc774\uce58\uac00 \uadf8\ub798</h2><a href=\\"https://polotek.net/posts/the-frontend-treadmill/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polotek.net/posts/the-frontend-treadmill/</a><p data-notion-block-id=\\"cce5d0e3-7a78-4248-952b-b9c5625abbe9\\">\uc0c8\ub85c\uc6b4 \uae30\uc220\uc774\ub098 \uc778\uae30\uc788\ub294 \uae30\uc220\uc744 \ubc30\uc6b0\uc9c0 \ub9d0\uace0 \ud575\uc2ec \uc6f9 \uae30\uc220\uc744 \ubc30\uc6b0\ub77c\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5ec\uae30\uc11c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \uac83\uc740 \ubaa8\ub4e0 \ubb38\uc81c\uc5d0 \ud574\ub2f5\uc774 \ub420 \uc218 \uc5c6\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc800\ub294 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc774\ub098 \uc778\uae30 \uc788\ub294 \uae30\uc220\uc774 \uc5c6\ub294 \uc694\uad6c\uc5d0 \uae30\ubc18\ud574\uc11c \ub9cc\ub4e4\uc5b4\uc84c\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ub300\ubd80\ubd84\uc740 \uc694\uad6c\uc5d0 \ub530\ub77c\uc11c \uc0dd\uacbc\uace0, \uc0c8\ub85c\uc6b4 \uae30\uc220\uc774\ub77c\uace0 \ud558\uc9c0\ub9cc, \uc774\uc804\uc5d0 \uc788\ub358 \uc694\uad6c\uc0ac\ud56d\uc5d0\uc11c \ud06c\uac8c \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0dd\uac01\uc744 \ud569\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubaa8\ub2c8\ud130\ub9c1\ud558\ub294 \uac83\uc740 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. 2014\ub144\uc5d0 \uc2dc\uc791\ub41c React\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uc9c0\uae08\uc740 \uaf64 \ub9ce\uc740 \uac83\ucc98\ub7fc\uc694. \ud558\uc9c0\ub9cc \uae30\ubc18, \ud575\uc2ec \uc9c0\uc2dd\uc744 \ubc30\uc6b0\ub294 \uac83 \ub610\ud55c \uc911\uc694\ud569\ub2c8\ub2e4. \ud575\uc2ec \uc9c0\uc2dd\uc744 \uae30\ubc18\uc73c\ub85c \ub9ce\uc740 \uae30\uc220\ub4e4\uc774 \uc0dd\uae30\ub2c8\uae4c\uc694. \ube44\uc728\uc744 \uc870\uc808\ud558\uba74\uc11c \uacc4\uc18d \uacf5\ubd80\ud574\ubcf4\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"87d31b27-2ae1-428c-8a87-9e2a1376ac9b\\" id=\\"87d31b27-2ae1-428c-8a87-9e2a1376ac9b\\">\uac04\ub2e8\ud55c UX \uacbd\ud5d8 \uc62c\ub9ac\uae30</h2><a href=\\"https://blog.jim-nielsen.com/2024/sanding-ui/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.jim-nielsen.com/2024/sanding-ui/</a><p data-notion-block-id=\\"bea4f0c8-a603-45af-aa19-1cf23e04a828\\"><code>margin</code>\uacfc <code>padding</code>\uc758 \ucc28\uc774\uc5d0\uc11c \uc624\ub294 UX \uacbd\ud5d8\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/295b308b-5e8d-472d-8662-05f74c3cfed3\\">\uc0c1\ud638\uc791\uc6a9 \ubc94\uc704 \ub354 \uc88b\uac8c\ud558\uae30</a>\uc640 \ube44\uc2b7\ud55c \uae00\uc774\ub124\uc694.</p>"}')}}]);